PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(digest TEXT PRIMARY KEY, user_id INTEGER REFERENCES users ON DELETE CASCADE, csrf TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tokens(digest TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users ON DELETE CASCADE, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS limits(key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY, owner INTEGER NOT NULL REFERENCES users ON DELETE CASCADE, title TEXT NOT NULL, date TEXT NOT NULL, budget TEXT NOT NULL, invitation TEXT NOT NULL, postal INTEGER NOT NULL DEFAULT 0, public_code TEXT UNIQUE, retention INTEGER NOT NULL DEFAULT 24, expires INTEGER, history INTEGER NOT NULL DEFAULT 0, previous TEXT REFERENCES events ON DELETE SET NULL, drawn INTEGER, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS participants(id INTEGER PRIMARY KEY, event TEXT NOT NULL REFERENCES events ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users ON DELETE CASCADE, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','declined')), wishes TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', mail_status TEXT NOT NULL DEFAULT 'not_sent', mailed INTEGER, UNIQUE(event,user_id));
CREATE TABLE IF NOT EXISTS exclusions(event TEXT NOT NULL REFERENCES events ON DELETE CASCADE, giver INTEGER NOT NULL REFERENCES participants ON DELETE CASCADE, receiver INTEGER NOT NULL REFERENCES participants ON DELETE CASCADE, PRIMARY KEY(event,giver,receiver));
CREATE TABLE IF NOT EXISTS assignments(event TEXT NOT NULL REFERENCES events ON DELETE CASCADE, giver INTEGER NOT NULL REFERENCES participants ON DELETE CASCADE, receiver INTEGER NOT NULL REFERENCES participants ON DELETE CASCADE, PRIMARY KEY(event,giver), UNIQUE(event,receiver));
CREATE TABLE IF NOT EXISTS draw_mail(event TEXT NOT NULL REFERENCES events ON DELETE CASCADE, participant INTEGER NOT NULL REFERENCES participants ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'queued', attempts INTEGER NOT NULL DEFAULT 0, next_attempt INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(event,participant));
CREATE INDEX IF NOT EXISTS participant_event ON participants(event);
CREATE INDEX IF NOT EXISTS session_expiry ON sessions(expires);
CREATE INDEX IF NOT EXISTS token_expiry ON tokens(expires);
